var source := load("res://scenes/game/game_session.tscn") as PackedScene
if source == null:
    _custom_print("session load failed")
else:
    var root := source.instantiate()
    var map_small := root.get_node_or_null("MapSmall") as Node2D
    var map_large := root.get_node_or_null("MapLarge") as Node2D
    var medium := root.get_node_or_null("MapMedium") as Node2D
    if medium != null:
        medium.visible = true
        var medium_boundary := medium.get_node_or_null("FallBoundary") as Area2D
        if medium_boundary != null:
            medium_boundary.monitoring = true
    if map_small != null:
        map_small.visible = false
        var small_boundary := map_small.get_node_or_null("FallBoundary") as Area2D
        if small_boundary != null:
            small_boundary.monitoring = false
    if map_large != null:
        map_large.visible = false
        var large_boundary := map_large.get_node_or_null("FallBoundary") as Area2D
        if large_boundary != null:
            large_boundary.monitoring = false
    var packed := PackedScene.new()
    var pack_error := packed.pack(root)
    var save_error := ResourceSaver.save(packed, "res://scenes/game/game_session.tscn")
    root.free()
    _custom_print("restore %s %s" % [error_string(pack_error), error_string(save_error)])
